import { readFileSync } from 'node:fs'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'replay' && mode[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(field, text, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

// Token counts are scaled by `per` so fractions stay exact.
function makeBucket(name, capacity, refill, per) {
  const states = new Map()
  const cap = capacity * per
  return {
    name,
    advance(key, tick) {
      const s = states.get(key)
      if (!s) {
        states.set(key, { t: cap, last: tick })
        return
      }
      s.t += refill * (tick - s.last)
      if (s.t > cap) s.t = cap
      s.last = tick
    },
    allows: (key) => states.get(key).t >= per,
    record(key) { states.get(key).t -= per },
  }
}

function makeWindow(name, limit, span) {
  const states = new Map()
  return {
    name,
    advance(key, tick) {
      let s = states.get(key)
      if (!s) states.set(key, (s = []))
      const cutoff = tick - span
      while (s.length && s[0] <= cutoff) s.shift()
    },
    allows: (key) => BigInt(states.get(key).length) < limit,
    record(key, tick) { states.get(key).push(tick) },
  }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let prev = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    const d = w[0]
    try {
      if (d !== 'bucket' && d !== 'window' && d !== 'route' && d !== 'event') {
        throw new Fail(`unknown directive ${d}`)
      }
      if (d !== 'event' && started) throw new Fail('declarations must come before the first event')
      if (d === 'bucket') {
        if (w.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        const c = int('capacity', w[2], 1)
        const r = int('refill', w[3], 0)
        const p = int('per', w[4], 1)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], () => makeBucket(w[1], c, r, p))
      } else if (d === 'window') {
        if (w.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        const l = int('limit', w[2], 0)
        const s = int('span', w[3], 1)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], () => makeWindow(w[1], l, s))
      } else if (d === 'route') {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        for (const n of w.slice(2)) if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
        routes.set(w[1], w.slice(2).map((n) => policies.get(n)()))
      } else {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const t = int('tick', w[1], 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (prev !== null && t < prev) throw new Fail(`tick ${t} is before tick ${prev}`)
        prev = t
        started = true
        events.push([t, w[1], w[2]])
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function route(routes, key) {
  let best = null
  for (const p of routes.keys()) {
    if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
  }
  return best === null ? [] : routes.get(best)
}

let out = ''
try {
  const { routes, events } = parse(readFileSync(0, 'utf8'))
  const stats = new Map()
  let ta = 0
  let td = 0
  for (const [tick, text, key] of events) {
    const ps = route(routes, key)
    for (const p of ps) p.advance(key, tick)
    const refuser = ps.find((p) => !p.allows(key))
    if (!refuser) for (const p of ps) p.record(key, tick)
    if (!stats.has(key)) stats.set(key, [0, 0])
    stats.get(key)[refuser ? 1 : 0]++
    if (refuser) td++
    else ta++
    if (mode[0] === 'replay') out += refuser ? `${text} ${key} deny ${refuser.name}\n` : `${text} ${key} allow\n`
  }
  if (mode[0] === 'summary') {
    for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      out += `${k} allowed=${stats.get(k)[0]} denied=${stats.get(k)[1]}\n`
    }
    out += `total allowed=${ta} denied=${td}\n`
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
